			//	yield break;

			//}

			//var dur = float.Parse(durString);

			//yield return new WaitForSeconds(dur);
			//onFinishCallback.Invoke(this);

			var dur = Dur.GetValueOrDefault();

			if (dur > 0)
			{
				var timePast = 0f;

				while (timePast < dur)
				{
					yield return null;
					if (Suspended)
					{
						continue;
					}
					timePast += Time.deltaTime;
				}
			} else if (dur < 0)
			{
				int framesDur = (int) dur;
				int framesPast = 0;

				while (framesPast < framesDur)
				{
					yield return null;
					if (Suspended)
					{
						continue;
					}
					framesPast++;
				}

			}

			onFinishCallback.Invoke(this);
			yield break;
		}
	}
