        public void RaiseFromPressAndRelease(InputAction.CallbackContext ctx)
        {
            if (ctx.performed)
            {
                Raise(true);
                return;
            }

            if (ctx.canceled)
            {
                Raise(false);
                return;
            }
        }
    }
